     * the manual ceiling: it retunes the encoder and moves the reservation.
     */
    func encodeVideo(input: MoqVideoEncoderInput, output: MoqVideoEncoderOutput, bandwidth: MoqBandwidth?) throws  -> MoqVideoProducer
    
}
